#!/usr/bin/env python3
"""
Generate the final analysis report comparing base case and counterfactual scenarios
"""

import json
import sys

def main():
    # Load results
    with open('results_base.json', 'r') as f:
        results_base = json.load(f)

    with open('results_cf.json', 'r') as f:
        results_cf = json.load(f)

    # Extract LMPs
    lmp_base = results_base['lmp_by_bus']
    lmp_cf = results_cf['lmp_by_bus']

    # Calculate LMP deltas
    lmp_deltas = {}
    for bus_str in lmp_base.keys():
        bus = int(bus_str)
        delta = float(lmp_cf.get(str(bus), 0)) - float(lmp_base.get(str(bus), 0))
        lmp_deltas[bus] = {
            'base_lmp': float(lmp_base.get(str(bus), 0)),
            'cf_lmp': float(lmp_cf.get(str(bus), 0)),
            'delta': delta
        }

    # Sort by largest price drop (most negative delta)
    largest_drops = sorted(
        [(bus, data) for bus, data in lmp_deltas.items()],
        key=lambda x: x[1]['delta']
    )[:3]

    # Check if line 64-1501 is binding in counterfactual
    target_binding = False
    for line in results_cf['binding_lines']:
        if (line['from'] == 64 and line['to'] == 1501) or \
           (line['from'] == 1501 and line['to'] == 64):
            target_binding = True
            break

    congestion_relieved = not target_binding

    # Prepare LMP lists for report
    lmp_list_base = [
        {'bus': bus, 'lmp_dollars_per_MWh': lmp_deltas[bus]['base_lmp']}
        for bus in sorted(lmp_deltas.keys())
    ]

    lmp_list_cf = [
        {'bus': bus, 'lmp_dollars_per_MWh': lmp_deltas[bus]['cf_lmp']}
        for bus in sorted(lmp_deltas.keys())
    ]

    # Build the report
    report = {
        'base_case': {
            'total_cost_dollars_per_hour': float(results_base['total_cost']),
            'lmp_by_bus': lmp_list_base,
            'reserve_mcp_dollars_per_MWh': float(results_base['reserve_mcp']),
            'binding_lines': results_base['binding_lines']
        },
        'counterfactual': {
            'total_cost_dollars_per_hour': float(results_cf['total_cost']),
            'lmp_by_bus': lmp_list_cf,
            'reserve_mcp_dollars_per_MWh': float(results_cf['reserve_mcp']),
            'binding_lines': results_cf['binding_lines']
        },
        'impact_analysis': {
            'cost_reduction_dollars_per_hour': float(results_base['total_cost']) - float(results_cf['total_cost']),
            'buses_with_largest_lmp_drop': [
                {
                    'bus': int(bus),
                    'base_lmp': data['base_lmp'],
                    'cf_lmp': data['cf_lmp'],
                    'delta': data['delta']
                }
                for bus, data in largest_drops
            ],
            'congestion_relieved': congestion_relieved
        }
    }

    # Save report
    with open('report.json', 'w') as f:
        json.dump(report, f, indent=2)

    print("Report generated successfully!")
    print(f"\nSummary:")
    print(f"  Base case cost: ${report['base_case']['total_cost_dollars_per_hour']:,.2f}")
    print(f"  Counterfactual cost: ${report['counterfactual']['total_cost_dollars_per_hour']:,.2f}")
    print(f"  Cost reduction: ${report['impact_analysis']['cost_reduction_dollars_per_hour']:,.2f}")
    print(f"  Congestion relieved: {congestion_relieved}")
    print(f"  Buses with largest LMP drop:")
    for item in report['impact_analysis']['buses_with_largest_lmp_drop']:
        print(f"    Bus {item['bus']}: {item['base_lmp']:.2f} → {item['cf_lmp']:.2f} (Δ = {item['delta']:.2f})")

if __name__ == '__main__':
    main()

