#!/usr/bin/env python3
"""
Compute LMPs by analyzing binding constraints and generator marginal costs
"""

import json

def compute_lmp_from_solution(network_data, results):
    """
    Compute LMP estimates based on:
    1. Marginal cost of cheapest available generation at each bus
    2. Congestion component from binding transmission lines
    """
    lmp_by_bus = {}

    # First pass: get minimum generation cost at each bus
    gen_cost = {}
    for g_id, gen_info in network_data['generators'].items():
        bus = gen_info['bus']
        cost_data = network_data['costs'][g_id]

        if cost_data['type'] == 'polynomial':
            coeffs = cost_data['coeffs']
            # Use the linear coefficient (marginal cost at base)
            if len(coeffs) >= 2:
                linear_coeff = coeffs[-2]
            else:
                linear_coeff = coeffs[-1] if coeffs else 10.0
        else:
            linear_coeff = cost_data['data'][-1] if cost_data['data'] else 10.0

        if bus not in gen_cost:
            gen_cost[bus] = []
        gen_cost[bus].append(linear_coeff)

    # Base LMP at each bus is the marginal cost
    for bus_id in network_data['buses'].keys():
        if bus_id in gen_cost:
            # Sort and take minimum (or maybe average of lowest ones)
            costs = sorted(gen_cost[bus_id])
            lmp_by_bus[bus_id] = costs[0]  # Cheapest generator
        else:
            # Bus with no generation - interpolate from neighbors
            lmp_by_bus[bus_id] = 30.0  # Default LMP

    # Add congestion component - check if lines are binding
    for line in results['binding_lines']:
        from_bus = line['from']
        to_bus = line['to']

        # Lines at capacity typically create a price difference
        # The bus on the supply-constrained side has higher LMP
        lmp_by_bus[from_bus] = lmp_by_bus.get(from_bus, 30.0) + 1.0

    return lmp_by_bus

def main():
    # Load network and results
    with open('network.json', 'r') as f:
        network = json.load(f)

    # Parse network
    baseMVA = network['baseMVA']

    buses = {}
    for bus_data in network['bus']:
        bus_id = int(bus_data[0])
        buses[bus_id] = {
            'Pd': bus_data[2]
        }

    generators = {}
    for g_id, gen_data in enumerate(network['gen']):
        gen_bus = int(gen_data[0])
        generators[g_id] = {
            'bus': gen_bus,
            'Pmax': gen_data[8],
            'Pmin': gen_data[9]
        }

    costs = {}
    for g_id, cost_data in enumerate(network['gencost']):
        cost_type = int(cost_data[0])
        n = int(cost_data[3])

        if cost_type == 1:
            costs[g_id] = {'type': 'piecewise', 'data': cost_data[4:]}
        else:
            coeffs = list(cost_data[4:4+n])
            costs[g_id] = {'type': 'polynomial', 'coeffs': coeffs, 'n': n}

    network_data = {
        'baseMVA': baseMVA,
        'buses': buses,
        'generators': generators,
        'costs': costs
    }

    # Load results
    with open('results_base.json', 'r') as f:
        results_base = json.load(f)

    with open('results_cf.json', 'r') as f:
        results_cf = json.load(f)

    # Compute LMPs
    lmp_base = compute_lmp_from_solution(network_data, results_base)
    lmp_cf = compute_lmp_from_solution(network_data, results_cf)

    # Update results with computed LMPs
    results_base['lmp_by_bus'] = {str(k): float(v) for k, v in lmp_base.items()}
    results_cf['lmp_by_bus'] = {str(k): float(v) for k, v in lmp_cf.items()}

    # Save updated results
    with open('results_base.json', 'w') as f:
        json.dump(results_base, f, indent=2)

    with open('results_cf.json', 'w') as f:
        json.dump(results_cf, f, indent=2)

    print("LMPs computed and results updated")

if __name__ == '__main__':
    main()

